def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my_last, opp_last = history[-1]

    if n == 99:
        return 'D'

    if opp_last == 'D':
        total_opp_def = sum(1 for _, o in history if o == 'D')
        if total_opp_def <= 1 and n > 10:
            return 'C'
        return 'D'

    total_my_def = sum(1 for m, _ in history if m == 'D')

    if total_my_def == 0:
        if n >= 10:
            return 'D'
        return 'C'

    count_myC = 0
    count_myC_oppC = 0
    count_myD = 0
    count_myD_oppC = 0
    for i in range(n - 1):
        my_act = history[i][0]
        opp_next = history[i+1][1]
        if my_act == 'C':
            count_myC += 1
            if opp_next == 'C':
                count_myC_oppC += 1
        else:
            count_myD += 1
            if opp_next == 'C':
                count_myD_oppC += 1

    if count_myC > 0:
        pC_myC = count_myC_oppC / count_myC
    else:
        pC_myC = 0.5

    if count_myD > 0:
        pC_myD = count_myD_oppC / count_myD
    else:
        pC_myD = 0.5

    if pC_myD >= pC_myC - 0.15:
        return 'D'
    else:
        return 'C'
